components.css:
.ds-btn-primary {
  background: var(--cream, #f4f0e6);
  color: var(--ink, #102033);
  padding: 12px 14px;
  min-height: 52px;
  border: 0;
  border-radius: 0;
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1.25;
  direction: rtl;
}
.ds-btn-primary:active { background: var(--cream-2, #e7e0d2); }
.ds-btn-primary:focus-visible {
  outline: 2px solid var(--cream, #f4f0e6);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px var(--navy, #071428);
}

.ds-btn-row { display: flex; gap: 8px; direction: rtl; }
.ds-btn-secondary {
  flex: 1;
  background: transparent;
  color: var(--cream, #f4f0e6);
  padding: 12px 14px;
  min-height: 52px;
  border: 0;
  border-radius: 0;
  box-shadow: inset 0 0 0 1px var(--line, rgba(244, 240, 230, 0.22));
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-size: 1.05rem;
  font-weight: 800;
  direction: rtl;
}
.ds-btn-secondary:active:not(:disabled) { background: rgba(244, 240, 230, 0.08); }
.ds-btn-secondary:disabled {
  color: #b7c2d1;
  box-shadow: inset 0 0 0 1px rgba(244, 240, 230, 0.18);
}
.ds-btn-secondary:focus-visible {
  outline: 2px solid var(--cream, #f4f0e6);
  outline-offset: 3px;
}

.ds-btn-ghost {
  display: block;
  width: 100%;
  background: transparent;
  color: var(--cream, #f4f0e6);
  padding: 12px 14px;
  min-height: 52px;
  border: 0;
  border-radius: 0;
  box-shadow: inset 0 0 0 1px var(--line, rgba(244, 240, 230, 0.22));
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-size: 1.05rem;
  font-weight: 800;
  direction: rtl;
}
.ds-btn-ghost:active { background: rgba(244, 240, 230, 0.08); }
.ds-btn-ghost:focus-visible {
  outline: 2px solid var(--cream, #f4f0e6);
  outline-offset: 3px;
}

.ds-era {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line, rgba(244, 240, 230, 0.22));
  border-radius: 0;
  direction: rtl;
}
.ds-chip {
  min-height: 48px;
  padding: 10px 8px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--cream, #f4f0e6);
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-size: 0.98rem;
  font-weight: 700;
}
.ds-chip-on { background: var(--amber, #f5c518); color: var(--navy, #071428); }
.ds-chip:focus-visible {
  outline: 2px solid var(--cream, #f4f0e6);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px var(--navy, #071428);
}

.ds-mode {
  display: grid;
  grid-template-columns: 28px 1fr auto;
  gap: 12px;
  align-items: center;
  width: 100%;
  min-height: 76px;
  padding: 14px 2px;
  border: 0;
  border-radius: 0;
  border-top: 1px solid var(--line, rgba(244, 240, 230, 0.22));
  border-bottom: 1px solid var(--line, rgba(244, 240, 230, 0.22));
  background: transparent;
  color: var(--cream, #f4f0e6);
  text-align: right;
  direction: rtl;
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
}
.ds-mode-icon svg {
  width: 22px;
  height: 22px;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.ds-mode-icon svg circle { fill: currentColor; stroke: none; }
.ds-mode-copy { display: flex; flex-direction: column; gap: 2px; }
.ds-mode-title { font-size: 1.2rem; font-weight: 800; line-height: 1.2; }
.ds-mode-sub { font-size: 0.92rem; font-weight: 500; color: var(--muted, #d5dce8); }
.ds-mode-best {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 3.2rem;
  color: var(--muted, #d5dce8);
  font-size: 0.75rem;
  font-weight: 700;
}
.ds-mode-best b {
  font-family: var(--display, "Secular One", "Heebo", sans-serif);
  font-weight: 400;
  font-size: 1.45rem;
  line-height: 1;
  color: var(--cream, #f4f0e6);
  font-variant-numeric: tabular-nums;
}
@media (hover: hover) {
  .ds-mode:hover { background: rgba(244, 240, 230, 0.06); }
}
.ds-mode:active { background: rgba(244, 240, 230, 0.08); }
.ds-mode:focus-visible {
  outline: 2px solid var(--cream, #f4f0e6);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px var(--navy, #071428);
}

.ds-answers { display: grid; grid-template-columns: 1fr; gap: 8px; direction: rtl; }
.ds-ans {
  min-height: 52px;
  padding: 10px 14px;
  border: 0;
  border-radius: 0;
  background: var(--cream, #f4f0e6);
  color: var(--ink, #102033);
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1.25;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
@media (hover: hover) {
  .ds-ans:hover:not(:disabled) { background: #fffdf8; }
}
.ds-ans:active:not(:disabled) { background: var(--cream-2, #e7e0d2); }
.ds-ans-correct { background: var(--good, #0c5c34); color: var(--on-good, #f4f0e6); }
.ds-ans-wrong { background: var(--bad, #8e1e1a); color: var(--on-bad, #f4f0e6); }
.ds-ans-dim { background: #e4dccb; color: var(--muted-ink, #3e4c5e); }
.ds-ans-correct::after,
.ds-ans-wrong::after {
  content: "";
  width: 16px;
  height: 16px;
  flex: none;
  background: currentColor;
  -webkit-mask: var(--ds-mark) center / contain no-repeat;
  mask: var(--ds-mark) center / contain no-repeat;
}
.ds-ans-correct { --ds-mark: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'><path d='M5 12.5 10 17.5 19 7'/></svg>"); }
.ds-ans-wrong { --ds-mark: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round'><path d='M7 7l10 10M17 7 7 17'/></svg>"); }
.ds-ans:focus-visible {
  outline: 2px solid var(--cream, #f4f0e6);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px var(--navy, #071428);
}

.ds-score {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 4px;
  min-width: 76px;
  min-height: 44px;
  padding: 6px 10px;
  background: var(--amber, #f5c518);
  color: var(--navy, #071428);
  border-radius: 0;
  direction: rtl;
}
.ds-score-clip { overflow: hidden; height: 1.35rem; display: grid; align-items: center; }
.ds-score-num {
  font-family: var(--display, "Secular One", "Heebo", sans-serif);
  font-weight: 400;
  font-size: 1.35rem;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  display: block;
  animation: ds-bugstep 0.38s cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-score-unit {
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-size: 0.78rem;
  font-weight: 800;
}
@keyframes ds-bugstep {
  from { transform: translateY(70%); }
  to { transform: none; }
}

.ds-plate {
  background: var(--cream, #f4f0e6);
  color: var(--ink, #102033);
  border-radius: 0;
  direction: rtl;
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
}
.ds-lower {
  background: var(--amber, #f5c518);
  color: var(--navy, #071428);
  padding: 14px 16px 13px;
  animation: ds-wipe 0.42s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes ds-wipe {
  from { clip-path: inset(0 0 0 100%); }
  to { clip-path: inset(0 0 0 0); }
}
.ds-lower-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}
.ds-question {
  margin: 0;
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-size: 1.28rem;
  font-weight: 800;
  line-height: 1.35;
}
.ds-worth { margin: 0; font-size: 0.92rem; font-weight: 700; white-space: nowrap; }
.ds-worth b { font-variant-numeric: tabular-nums; }
.ds-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  padding: 10px 16px 0;
  color: var(--muted-ink, #3e4c5e);
  font-size: 0.82rem;
  font-weight: 700;
}
.ds-clubs {
  list-style: none;
  margin: 0;
  padding: 4px 16px 8px;
}
.ds-club {
  display: grid;
  grid-template-columns: 1.5rem minmax(0, 1fr) auto;
  gap: 10px;
  align-items: baseline;
  padding: 8px 0;
  border-bottom: 1px solid var(--line-ink, rgba(16, 32, 51, 0.14));
  font-size: 1.02rem;
  font-weight: 700;
}
.ds-club:last-child { border-bottom: 0; }
.ds-n { font-variant-numeric: tabular-nums; font-weight: 800; }
.ds-yr {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  font-size: 0.86rem;
  color: var(--muted-ink, #3e4c5e);
  direction: ltr;
  unicode-bidi: isolate;
}
.ds-club-locked span:nth-child(2),
.ds-club-locked .ds-yr { color: #4a433c; }

.ds-feedback-stack { display: flex; flex-direction: column; gap: 8px; direction: rtl; }
.ds-feedback {
  padding: 12px 14px;
  border-radius: 0;
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-weight: 700;
  font-size: 1rem;
  line-height: 1.35;
}
.ds-feedback-good { background: var(--good, #0c5c34); color: var(--on-good, #f4f0e6); }
.ds-feedback-bad { background: var(--bad, #8e1e1a); color: var(--on-bad, #f4f0e6); }

.ds-end { direction: rtl; text-align: center; }
.ds-result {
  margin: 0 -18px;
  padding: 16px 18px 14px;
  background: var(--amber, #f5c518);
  color: var(--navy, #071428);
  border-radius: 0;
  font-family: var(--display, "Secular One", "Heebo", sans-serif);
  font-weight: 400;
  font-size: clamp(4.6rem, 24vw, 6rem);
  line-height: 0.9;
  font-variant-numeric: tabular-nums;
}
.ds-result small {
  display: block;
  margin-top: 6px;
  font-family: var(--font, "Heebo", "Arial Hebrew", Arial, sans-serif);
  font-size: 0.95rem;
  font-weight: 800;
  line-height: 1.2;
}
.ds-record {
  margin-top: 8px;
  font-family: var(--display, "Secular One", "Heebo", sans-serif);
  font-weight: 400;
  font-size: 1.85rem;
  color: var(--cream, #f4f0e6);
}
